import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";

export default function EventPage({ token }) {
  const { id } = useParams();
  const navigate = useNavigate();

  const [event, setEvent] = useState(null);
  const [msg, setMsg] = useState("");

  // Load event
  useEffect(() => {
    fetch(
      (process.env.REACT_APP_API || "http://localhost:4000") +
        "/api/dashboard/events/" +
        id
    )
      .then((r) => {
        if (!r.ok) throw new Error("Not found");
        return r.json();
      })
      .then(setEvent)
      .catch(() => setEvent(null));
  }, [id]);

  // Volunteer button
  async function volunteer() {
    if (!token) {
      navigate("/login");
      return;
    }

    try {
      const res = await fetch(
        (process.env.REACT_APP_API || "http://localhost:4000") +
          "/api/actions/volunteer",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({ event_id: id }),
        }
      );

      const d = await res.json();
      setMsg(d.message || "Registered");
    } catch (e) {
      setMsg("Error registering");
    }
  }

  if (event === null)
    return <div className="event-page">Event not found or loading...</div>;

  return (
    <div className="event-page">
      <h2>{event.title}</h2>

      <img
        src={event.image_url || event.image || "https://tse4.mm.bing.net/th/id/OIP.ZBmeV9S22ak8-r9pRW3XgAHaFj?pid=Api&P=0&h=180"}
        alt={event.title}
        style={{
          width: "100%",
          height: 320,
          objectFit: "cover",
          borderRadius: 8,
        }}
      />

      <p style={{ marginTop: 12 }}>{event.description}</p>

      <div style={{ marginTop: 12 }}>
        <button className="buttons primary" onClick={volunteer}>
          Volunteer / Participate
        </button>

        <button
          className="buttons"
          onClick={() => navigate("/login")}
          style={{ marginLeft: 8 }}
        >
          Login to Participate
        </button>

        <button
          className="buttons"
          onClick={() => navigate("/register")}
          style={{ marginLeft: 8 }}
        >
          Register
        </button>
      </div>

      {msg && (
        <p style={{ marginTop: 12, color: "green" }}>
          {msg}
        </p>
      )}
    </div>
  );
}
